<?php
require 'helpers.php'; requerirLogin();
if(!puede('ver_reportes')){http_response_code(403);exit('Tu rol no tiene permiso para ver reportes.');}
$clienteId=esSuper()?(int)($_GET['cliente']??usuario()['cliente_id']):(int)usuario()['cliente_id'];
$q=db()->prepare('SELECT nombre_empresa FROM costobene_clientes WHERE id=?');$q->execute([$clienteId]);$nombreEmpresa=(string)$q->fetchColumn();
$ps=db()->prepare('SELECT id,nombre,unidad,moneda,volumen_esperado,margen_porcentaje,precio_manual FROM costobene_productos WHERE cliente_id=? ORDER BY nombre');$ps->execute([$clienteId]);$productos=$ps->fetchAll();
$filas=[];
foreach($productos as $p){
 $cs=db()->prepare("SELECT c.tipo_costo,COALESCE(SUM(COALESCE(m.monto_asignado,c.monto)),0) total FROM costobene_costos_producto c LEFT JOIN costobene_costos_productos_compartidos m ON m.costo_id=c.id AND m.producto_id=? WHERE c.estado_aprobacion='aprobado' AND (m.producto_id IS NOT NULL OR (c.producto_id=? AND NOT EXISTS (SELECT 1 FROM costobene_costos_productos_compartidos mx WHERE mx.costo_id=c.id))) GROUP BY c.tipo_costo");$cs->execute([$p['id'],$p['id']]);$sum=['fixed'=>0,'variable'=>0,'indirect'=>0,'labor'=>0];foreach($cs as $c){$sum[$c['tipo_costo']]=(float)$c['total'];}
 $vol=(float)$p['volumen_esperado'];$fijos=$sum['fixed']+$sum['indirect']+$sum['labor'];$variable=$sum['variable'];$costoUnit=$vol>0?($fijos/$vol)+$variable:0;$margen=(float)$p['margen_porcentaje']/100;$sugerido=$margen<1?$costoUnit/(1-$margen):0;$precio=($p['precio_manual']!==null&&(float)$p['precio_manual']>0)?(float)$p['precio_manual']:$sugerido;$ingreso=$vol*$precio;$costoTotal=$fijos+$variable*$vol;$ganancia=$ingreso-$costoTotal;
 $filas[]=['id'=>(int)$p['id'],'producto'=>$p['nombre'],'unidad'=>$p['unidad'],'moneda'=>$p['moneda'],'volumen'=>$vol,'precio'=>$precio,'ingresos'=>$ingreso,'costos_fijos'=>$sum['fixed'],'costos_variables_unitarios'=>$variable,'costos_indirectos'=>$sum['indirect'],'mano_obra'=>$sum['labor'],'costos_totales'=>$costoTotal,'ganancia'=>$ganancia,'margen_real'=>$ingreso>0?($ganancia/$ingreso)*100:0,'punto_equilibrio'=>$precio>$variable?(int)ceil($fijos/($precio-$variable)):null,'punto_equilibrio_ventas'=>$precio>$variable?(int)ceil($fijos/($precio-$variable))*$precio:null,'rentable'=>$ganancia>0];
}
$totalesPorMoneda=[]; foreach($filas as $fila){$m=$fila['moneda'];if(!isset($totalesPorMoneda[$m]))$totalesPorMoneda[$m]=['ingresos'=>0,'costos'=>0,'ganancia'=>0,'cantidad'=>0];$totalesPorMoneda[$m]['ingresos']+=$fila['ingresos'];$totalesPorMoneda[$m]['costos']+=$fila['costos_totales'];$totalesPorMoneda[$m]['ganancia']+=$fila['ganancia'];$totalesPorMoneda[$m]['cantidad']++;}
$exportar=array_map(function($r){return ['Producto/Servicio'=>$r['producto'],'Moneda'=>$r['moneda'],'Volumen esperado'=>$r['volumen'],'Precio de venta'=>$r['precio'],'Ingresos estimados'=>$r['ingresos'],'Costos fijos'=>$r['costos_fijos'],'Costos variables por unidad'=>$r['costos_variables_unitarios'],'Costos indirectos'=>$r['costos_indirectos'],'Mano de obra'=>$r['mano_obra'],'Costos totales'=>$r['costos_totales'],'Ganancia / pérdida'=>$r['ganancia'],'Margen real (%)'=>round($r['margen_real'],2),'Punto de equilibrio (unidades)'=>$r['punto_equilibrio'],'Facturación de equilibrio'=>$r['punto_equilibrio_ventas']];},$filas);
$resumenExportar=[];foreach($totalesPorMoneda as $m=>$t){$resumenExportar[]=['Moneda'=>$m,'Ingresos estimados'=>$t['ingresos'],'Costos estimados'=>$t['costos'],'Resultado estimado'=>$t['ganancia'],'Cantidad de productos/servicios'=>$t['cantidad']];}
$paginaActual='reportes';
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reportes - CostoPyme</title><link rel="stylesheet" href="style.css"></head><body><div class="app-shell"><?php require 'menu.php';?><main class="main">
<header class="page-head"><div><h1>Reportes</h1><p>Resultados estimados, estructura de costos y punto de equilibrio de tus productos y servicios.</p></div></header>
<?php if(esSuper()):$clientes=db()->query('SELECT id,nombre_empresa FROM costobene_clientes WHERE activo=1 ORDER BY nombre_empresa')->fetchAll();?><section class="panel"><label style="max-width:360px">Cliente<select onchange="location.href='reportes.php?cliente='+this.value"><?php foreach($clientes as $c):?><option value="<?=(int)$c['id']?>" <?=(int)$c['id']===$clienteId?'selected':''?>><?=h($c['nombre_empresa'])?></option><?php endforeach;?></select></label></section><?php endif;?>
<div class="panel"><h2><?=h($nombreEmpresa)?> · Resumen general</h2><?php if(!$totalesPorMoneda):?><div class="empty">Todavía no hay datos para calcular.</div><?php else: foreach($totalesPorMoneda as $moneda=>$t):?><h3><?=h($moneda)?></h3><div class="kpis"><div class="kpi"><small>Ingresos estimados</small><b><?=h($moneda)?> <?=number_format($t['ingresos'],2,',','.')?></b></div><div class="kpi"><small>Costos estimados</small><b><?=h($moneda)?> <?=number_format($t['costos'],2,',','.')?></b></div><div class="kpi"><small>Resultado estimado</small><b class="<?=$t['ganancia']>=0?'positive':'negative'?>"><?=h($moneda)?> <?=number_format($t['ganancia'],2,',','.')?></b></div><div class="kpi"><small>Productos / servicios</small><b><?=$t['cantidad']?></b></div></div><?php endforeach; endif;?><p class="help" style="margin-top:12px">Los resultados se calculan con el volumen esperado y los costos cargados. Los totales se presentan separados por moneda para evitar sumar importes de distintas divisas.</p></div>
<section class="panel"><h2>Rentabilidad por producto o servicio</h2><?php if(!$filas):?><div class="empty">Todavía no hay productos o servicios para generar reportes.</div><?php else:?><div class="table-wrap"><table id="tablaReporte"><thead><tr><th>Producto / servicio</th><th>Moneda</th><th class="num">Volumen</th><th class="num">Ingresos</th><th class="num">Costos</th><th class="num">Ganancia / pérdida</th><th class="num">Margen</th><th class="num">Punto de equilibrio (unidades)</th><th class="num">Facturación de equilibrio</th></tr></thead><tbody><?php foreach($filas as $r):?><tr><td><?=h($r['producto'])?></td><td><?=h($r['moneda'])?></td><td class="num"><?=number_format($r['volumen'],2,',','.')?></td><td class="num"><?=number_format($r['ingresos'],2,',','.')?></td><td class="num"><?=number_format($r['costos_totales'],2,',','.')?></td><td class="num <?=$r['ganancia']>=0?'positive':'negative'?>"><?=number_format($r['ganancia'],2,',','.')?></td><td class="num"><?=number_format($r['margen_real'],1,',','.')?>%</td><td class="num"><?=$r['punto_equilibrio']===null?'No se alcanza':number_format($r['punto_equilibrio'],0,',','.')?></td><td class="num"><?=$r['punto_equilibrio_ventas']===null?'No se alcanza':h($r['moneda']).' '.number_format($r['punto_equilibrio_ventas'],2,',','.')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="panel"><h2>Detalle de costos y evaluación</h2><?php if($filas):?><div class="table-wrap"><table><thead><tr><th>Producto / servicio</th><th>Fijos</th><th>Variables por unidad</th><th>Indirectos</th><th>Mano de obra</th><th>Evaluación</th></tr></thead><tbody><?php foreach($filas as $r):?><tr><td><?=h($r['producto'])?></td><td><?=h($r['moneda'])?> <?=number_format($r['costos_fijos'],2,',','.')?></td><td><?=h($r['moneda'])?> <?=number_format($r['costos_variables_unitarios'],2,',','.')?></td><td><?=h($r['moneda'])?> <?=number_format($r['costos_indirectos'],2,',','.')?></td><td><?=h($r['moneda'])?> <?=number_format($r['mano_obra'],2,',','.')?></td><td><span class="pill" style="background:<?=$r['ganancia']>0?'#dcfce7':($r['ganancia']<0?'#fee2e2':'#f1f5f9')?>;color:<?=$r['ganancia']>0?'#166534':($r['ganancia']<0?'#991b1b':'#475569')?>"><?=$r['ganancia']>0?'Rentable':($r['ganancia']<0?'No rentable':'En equilibrio')?></span></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
</main></div>
<div class="download-fab no-print"><div class="download-menu" id="downloadMenu"><button class="pdf" type="button" onclick="descargarPDF()">▧ Descargar reporte PDF</button><button class="xlsx" type="button" onclick="descargarXLSX()">▦ Descargar Excel XLSX</button></div><button type="button" onclick="document.getElementById('downloadMenu').classList.toggle('open')">↓ Descargar reporte</button></div>
<script src="https://cdn.jsdelivr.net/npm/jspdf@2.5.1/dist/jspdf.umd.min.js"></script><script src="https://cdn.jsdelivr.net/npm/jspdf-autotable@3.8.4/dist/jspdf.plugin.autotable.min.js"></script><script src="https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js"></script>
<script>
const reporte=<?=json_encode($exportar,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;
const empresa=<?=json_encode($nombreEmpresa,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;
const resumen=<?=json_encode($resumenExportar,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)?>;
function descargarXLSX(){if(!window.XLSX){alert('No se pudo cargar el módulo de Excel. Revisá tu conexión e intentá nuevamente.');return;}const wb=XLSX.utils.book_new();const ws=XLSX.utils.json_to_sheet(reporte);XLSX.utils.book_append_sheet(wb,ws,'Rentabilidad');const wr=XLSX.utils.json_to_sheet(resumen);XLSX.utils.book_append_sheet(wb,wr,'Resumen por moneda');XLSX.writeFile(wb,'CostoPyme_reporte_'+new Date().toISOString().slice(0,10)+'.xlsx');}
function descargarPDF(){if(!window.jspdf){alert('No se pudo cargar el módulo PDF. Revisá tu conexión e intentá nuevamente.');return;}const {jsPDF}=window.jspdf;const doc=new jsPDF({orientation:'landscape'});doc.setFontSize(18);doc.text('Reporte de rentabilidad - CostoPyme',14,16);doc.setFontSize(10);doc.text(empresa+' · Generado: '+new Date().toLocaleDateString('es-AR'),14,23);const cols=['Producto / servicio','Moneda','Volumen','Ingresos','Costos','Ganancia','Margen %','Punto equilibrio (unidades)','Facturación de equilibrio'];const rows=reporte.map(r=>[r['Producto/Servicio'],r.Moneda,r['Volumen esperado'],r['Ingresos estimados'].toFixed(2),r['Costos totales'].toFixed(2),r['Ganancia / pérdida'].toFixed(2),r['Margen real (%)'],r['Punto de equilibrio (unidades)']??'No se alcanza',r['Facturación de equilibrio']??'No se alcanza']);doc.autoTable({head:[cols],body:rows,startY:30,styles:{fontSize:8},headStyles:{fillColor:[36,87,166]}});doc.save('CostoPyme_reporte_'+new Date().toISOString().slice(0,10)+'.pdf');}
document.addEventListener('click',e=>{if(!e.target.closest('.download-fab'))document.getElementById('downloadMenu').classList.remove('open');});
</script></body></html>
